<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Service\Visibility\UserFederatedIdentityVisibilityService;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCommandRepositoryGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserFederatedIdentityVisibilityService $visibility,
        private readonly UserFederatedIdentityCommandRepositoryGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for User federated identity");
        $span = $this->startSpan("Check allow of create usecase for User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(UserFederatedIdentityCreateParams $params): UserFederatedIdentityCreateResult
    {
        $this->logDebug("Run create usecase for User federated identity");
        $span = $this->startSpan("Run create usecase for User federated identity");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create User federated identity');
            }
            $this->dispatcher->dispatch(new UserFederatedIdentityCreateCheck($params));
            $attributes = $this->visibility->copyWithFixed($params->toAttributes());
            $enriched = $this->dispatcher->dispatch(new UserFederatedIdentityCreateEnrich($params, $attributes));
            $input = $enriched->getEnrichedAttributes();
            $entity = UserFederatedIdentity::create($input);
            $result = $this->writer->create(
                $entity,
                fn (UserFederatedIdentity $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserFederatedIdentityCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
